(6764484, 1014546, 15711, '<td valign="top">I forget how spindly sheep''s legs are LOL  This is great.  Made me smile. :)</td>', 'I forget how spindly sheep''s legs are LOL  This is great.  Made me smile. :)', '2012-05-09 10:14:17.000000', NULL, 1),
(6764486, 1014359, 15711, '<td valign="top">That golden opposition to its complimentary blue is really good.  Very peaceful. :)</td>', 'That golden opposition to its complimentary blue is really good.  Very peaceful. :)', '2012-05-09 10:14:52.000000', NULL, 1),
