(6764489, 1014376, 15711, '<td valign="top">I really love how the birds add some sense of movement beyond the waves.  Very nice.  This would make a lovely print really BIG, spanning a wall.</td>', 'I really love how the birds add some sense of movement beyond the waves.  Very nice.  This would make a lovely print really BIG, spanning a wall.', '2012-05-09 10:15:26.000000', NULL, 1),
(6764492, 1013868, 15711, '<td valign="top">I like the long exposures slight blur of the moving clouds. Fish eye?  I like the curve it creates. The horizon does seem slightly tilted to the left though. :)</td>', 'I like the long exposures slight blur of the moving clouds. Fish eye?  I like the curve it creates. The horizon does seem slightly tilted to the left though. :)', '2012-05-09 10:17:01.000000', NULL, 1),
(6764494, 1014065, 15711, '<td valign="top">Would it have killed it to slightly dodge the dandelions in the foreground?  Just a thought. :)</td>', 'Would it have killed it to slightly dodge the dandelions in the foreground?  Just a thought. :)', '2012-05-09 10:17:40.000000', NULL, 1),
(6764495, 1014603, 15711, '<td valign="top">I love the birds!!</td>', 'I love the birds!!', '2012-05-09 10:17:56.000000', NULL, 1),
(6764497, 1014408, 15711, '<td valign="top">I like the red shirt as a pop against the green of the sea and the orange of the sunset.  The horizon seems slightly tilted to the left, or is that just me? :)</td>', 'I like the red shirt as a pop against the green of the sea and the orange of the sunset.  The horizon seems slightly tilted to the left, or is that just me? :)', '2012-05-09 10:18:48.000000', NULL, 1),
