(6764520, 1013408, 67152, '<td valign="top">wonderful - the tones, colors, shapes, and composition are so appealing</td>', 'wonderful - the tones, colors, shapes, and composition are so appealing', '2012-05-09 10:30:14.000000', NULL, 1),
(6764523, 1014376, 67152, '<td valign="top">I really like this one - one of my better scores.  <br/> <br/>The lines created by the shore pull us in, the golden tones on the right complement the sky nicely.  The birds mirror the lines of the shore as well, providing extra interest and dots of good contrast.  I wonder about the border in this one - it almost seems a bit harsh for this scene.  Overall, I like it and would love to see this at higher res.<br/> <br/>From a processing perspective, it is a bit contrasty, but not overly so.</td>', 'I really like this one - one of my better scores.   The lines created by the shore pull us in, the golden tones on the right complement the sky nicely.  The birds mirror the lines of the shore as well, providing extra interest and dots of good contrast.  I wonder about the border in this one - it almost seems a bit harsh for this scene.  Overall, I like it and would love to see this at higher res. From a processing perspective, it is a bit contrasty, but not overly so.', '2012-05-09 10:34:59.000000', NULL, 1),
(6764554, 1014630, 73942, '<td valign="top">beautiful, jusy love that reflection</td>', 'beautiful, jusy love that reflection', '2012-05-09 11:15:10.000000', NULL, 1),
