(6764587, 1014371, 112739, '<td valign="top">Very nice!</td>', 'Very nice!', '2012-05-09 11:49:42.000000', NULL, 1),
(6764592, 1014536, 112739, '<td valign="top">Might be the winner! Wonderfully done. I was going back and forth with my entry from color to B&amp;W. This really works very well in B&amp;W. The tones and depth are fabulous without being overdone. The only thing that seems out of place in the image are the wind turbines.</td>', 'Might be the winner! Wonderfully done. I was going back and forth with my entry from color to B&W. This really works very well in B&W. The tones and depth are fabulous without being overdone. The only thing that seems out of place in the image are the wind turbines.', '2012-05-09 12:01:45.000000', NULL, 1),
(6764593, 1014176, 112739, '<td valign="top">Love this! Great job on exposure.</td>', 'Love this! Great job on exposure.', '2012-05-09 12:02:40.000000', NULL, 1),
