(6764617, 1014210, 112739, '<td valign="top">I''m putting this wonderful creation as the Red ribbon winner. Just a wonderful scene.</td>', 'I''m putting this wonderful creation as the Red ribbon winner. Just a wonderful scene.', '2012-05-09 12:25:01.000000', NULL, 1),
(6764631, 1013942, 83313, '<td valign="top">Seems a bit washed out to me, due to what appears to me to be backlighting. Shooting with the sun in this direction is difficult. If the sun had been to your back, you''d probably have a stronger foreground with a great blue sky.</td>', 'Seems a bit washed out to me, due to what appears to me to be backlighting. Shooting with the sun in this direction is difficult. If the sun had been to your back, you''d probably have a stronger foreground with a great blue sky.', '2012-05-09 12:44:57.000000', NULL, 1),
(6764632, 1014367, 42256, '<td valign="top">Beautiful location and a great choice of composition with the flowers in the foreground.  I wish the flowers were also in focus, and the scene had a bit more contrast!</td>', 'Beautiful location and a great choice of composition with the flowers in the foreground.  I wish the flowers were also in focus, and the scene had a bit more contrast!', '2012-05-09 12:46:34.000000', NULL, 1),
(6764635, 1014279, 42256, '<td valign="top">nice work with the leading lines - eyes goes straight to the sun and back to the rocks with the sunburst. Nicely composed and edited!</td>', 'nice work with the leading lines - eyes goes straight to the sun and back to the rocks with the sunburst. Nicely composed and edited!', '2012-05-09 12:47:44.000000', NULL, 1),
(6764639, 1014299, 42256, '<td valign="top">Beautiful clouds and nice work with the reflection and maintaining the sharpness of the scene.</td>', 'Beautiful clouds and nice work with the reflection and maintaining the sharpness of the scene.', '2012-05-09 12:49:04.000000', NULL, 1),
(6764643, 1014354, 42256, '<td valign="top">a mecca for landscape photographers indeed. I wish the shot was sharper and the light was not this harsh.  Also something in the foreground would have really made this shot stronger!</td>', 'a mecca for landscape photographers indeed. I wish the shot was sharper and the light was not this harsh.  Also something in the foreground would have really made this shot stronger!', '2012-05-09 12:50:38.000000', NULL, 1),
(6764646, 1014259, 42256, '<td valign="top">Nice composition, love scenes like these! B&amp;W was a nice thought but the processing could have been better.  Also it lacks sharpness that can really make this shot stand out imo.</td>', 'Nice composition, love scenes like these! B&W was a nice thought but the processing could have been better.  Also it lacks sharpness that can really make this shot stand out imo.', '2012-05-09 12:52:15.000000', NULL, 1),
(6764650, 1014442, 42256, '<td valign="top">while I like the reflections, harsh sun and lack of a subject (an interesting subject that is) makes this shot average imho.</td>', 'while I like the reflections, harsh sun and lack of a subject (an interesting subject that is) makes this shot average imho.', '2012-05-09 12:56:15.000000', NULL, 1),
