(6765320, 1014063, 101668, '<td valign="top">I love this and I suppose many voters regard it as anything but a landscape. Great one</td>', 'I love this and I suppose many voters regard it as anything but a landscape. Great one', '2012-05-10 06:13:43.000000', NULL, 1),
(6765321, 1014367, 101668, '<td valign="top">great use of thirds but I cannot understand why there are so many landscape pictures in the challenge with such soft focus. Colours ar dull too</td>', 'great use of thirds but I cannot understand why there are so many landscape pictures in the challenge with such soft focus. Colours ar dull too', '2012-05-10 06:16:04.000000', NULL, 1),
