(6766176, 1013599, 113900, '<td valign="top">I have a hard time seeing this as a landscape, but dangit I love the shot so much that I''m giving it a 9 anyway.  DNMC SchmeeNMC</td>', 'I have a hard time seeing this as a landscape, but dangit I love the shot so much that I''m giving it a 9 anyway.  DNMC SchmeeNMC', '2012-05-10 22:50:02.000000', NULL, 1),
