(6766211, 1014371, 113900, '<td valign="top">Absolutely love the foreground.  Beautiful.  9.   Looked at it again and upped the score to a ten.</td>', 'Absolutely love the foreground.  Beautiful.  9.   Looked at it again and upped the score to a ten.', '2012-05-10 23:14:41.000000', NULL, 1),
