(6766554, 1014550, 99263, '<td valign="top">Lovely clarity, great shot. 8</td>', 'Lovely clarity, great shot. 8', '2012-05-11 04:52:23.000000', NULL, 1),
(6766819, 1014492, 34192, '<td valign="top">I love this.  It is like an anti-landscape, a message, a simplification of the messy world into lines and shapes and tones.  And there is something about it, simultaneously dark and amusing, that holds my attention even with the lack of detail (kinda like when a friend slips and falls and you don''t want to laugh but you have to try really hard to suppress a giggle because you know it is inappropriate but you also know that, even in that dark sad moment, life''s absurdity is presenting itself and you recognize it...).  Anyway, I am reminded of those walking monstrosities in star wars and, at the same time, the Pixar lamp, and the movie, "Where have all the People Gone?" (which greatly influenced my childhood sensibilities). And so, in the end, I consider this a very successful image.  Thanks! 10 and a fav.</td>', 'I love this.  It is like an anti-landscape, a message, a simplification of the messy world into lines and shapes and tones.  And there is something about it, simultaneously dark and amusing, that holds my attention even with the lack of detail (kinda like when a friend slips and falls and you don''t want to laugh but you have to try really hard to suppress a giggle because you know it is inappropriate but you also know that, even in that dark sad moment, life''s absurdity is presenting itself and you recognize it...).  Anyway, I am reminded of those walking monstrosities in star wars and, at the same time, the Pixar lamp, and the movie, "Where have all the People Gone?" (which greatly influenced my childhood sensibilities). And so, in the end, I consider this a very successful image.  Thanks! 10 and a fav.', '2012-05-11 12:36:57.000000', NULL, 1),
(6766864, 1013408, 54446, '<td valign="top">Love the ocean motion implied by the silk water.  Probably my fav in this challenge.  IMHO, perfect comp.  Love the moodiness and good detail, too.  Excellent control of detail in the shadows and the highlights.  10</td>', 'Love the ocean motion implied by the silk water.  Probably my fav in this challenge.  IMHO, perfect comp.  Love the moodiness and good detail, too.  Excellent control of detail in the shadows and the highlights.  10', '2012-05-11 13:20:49.000000', NULL, 1),
(6766931, 1014536, 143722, '<td valign="top">I fell in love with this photo! congrats!</td>', 'I fell in love with this photo! congrats!', '2012-05-11 14:19:22.000000', NULL, 1),
(6766940, 1014050, 83313, '<td valign="top">Almost overlooked the little girl. Not much that''s more fun than exploring. Brings back some fond memories.</td>', 'Almost overlooked the little girl. Not much that''s more fun than exploring. Brings back some fond memories.', '2012-05-11 14:30:40.000000', NULL, 1),
(6766944, 1014309, 83313, '<td valign="top">Nice reflection, and a scene with good potential. However, they highlights in the sky are seriously blown and the horizon is noticeably tilted, the latter being an easy fix.</td>', 'Nice reflection, and a scene with good potential. However, they highlights in the sky are seriously blown and the horizon is noticeably tilted, the latter being an easy fix.', '2012-05-11 14:48:43.000000', NULL, 1),
(6766945, 1013599, 83313, '<td valign="top">Wonderful!She sees seashells by the seashore.</td>', 'Wonderful!She sees seashells by the seashore.', '2012-05-11 14:50:03.000000', NULL, 1),
(6766947, 1014549, 83313, '<td valign="top">Creepy looking. Conjures up scenes from horror movies. No doubt your intention.</td>', 'Creepy looking. Conjures up scenes from horror movies. No doubt your intention.', '2012-05-11 14:51:31.000000', NULL, 1),
(6766949, 1014356, 83313, '<td valign="top">Looks like a pleasant place to enjoy riding my bike.</td>', 'Looks like a pleasant place to enjoy riding my bike.', '2012-05-11 14:53:04.000000', NULL, 1),
(6766951, 1014660, 83313, '<td valign="top">A great location and good composition, but I think the midday sun keeps it from being all it could be.</td>', 'A great location and good composition, but I think the midday sun keeps it from being all it could be.', '2012-05-11 14:55:00.000000', NULL, 1),
(6766967, 1014559, 142473, '<td valign="top">I really like this image, but I think I would have cropped off the left a bit... it really steals the eye.</td>', 'I really like this image, but I think I would have cropped off the left a bit... it really steals the eye.', '2012-05-11 15:24:44.000000', NULL, 1),
(6766969, 1014359, 142473, '<td valign="top">Really nice calm to this scene.  I know you intentionally put the moon in the center... I''d however like to see a comparison to it being at 1/3.  Maybe more impactful as is.  Either way, I really like it.</td>', 'Really nice calm to this scene.  I know you intentionally put the moon in the center... I''d however like to see a comparison to it being at 1/3.  Maybe more impactful as is.  Either way, I really like it.', '2012-05-11 15:28:24.000000', NULL, 1);
