INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6788421, 1014543, 100831, '<td valign="top">YES, I enjoy the experiments.. YES, I like this shot for it''s individual-ness. I love the color most of all.</td>', 'YES, I enjoy the experiments.. YES, I like this shot for it''s individual-ness. I love the color most of all.', '2012-06-06 23:15:58.000000', NULL, 0),
(6809512, 1014651, 66267, '<td valign="top">this is excellent</td>', 'this is excellent', '2012-07-05 09:48:39.000000', NULL, 0),
(6811308, 1014651, 66267, '<td valign="top">let me try to expand on that, because i think it''s important as to why i like certain photographs. some of my favourite kinds of photographs are the ones that make you curious about what''s outside the frame, or what isn''t being seen. these are mysterious to me. for example, one of my favourite photographs is hanging in my grandmothers house. i would always be fascinated by it as a kid; it''s a shot of an armchair in a living room, being backlit by sunny billowy curtains. the best part of the photograph isn''t the armchair, or anything in the scene for that matter. it''s the fact that against behind the curtains, you can see the outlines of tree branches on a summer day. nothing more than vague outlines. i''ve always been fascinated by what lay behind that curtain; it''s a whole world that i''ll never get to see, probably a scene lost forever. it was the most mysterious thing in the universe, and i would always try to imagine what that summer day looked like behind those curtains. this is kind of what this photograph is like for me. i want to see what''s behind those hills, what the sides of this scene is like, the things you can''t see that are just outside of the frame. it''s fascinating.</td>', 'let me try to expand on that, because i think it''s important as to why i like certain photographs. some of my favourite kinds of photographs are the ones that make you curious about what''s outside the frame, or what isn''t being seen. these are mysterious to me. for example, one of my favourite photographs is hanging in my grandmothers house. i would always be fascinated by it as a kid; it''s a shot of an armchair in a living room, being backlit by sunny billowy curtains. the best part of the photograph isn''t the armchair, or anything in the scene for that matter. it''s the fact that against behind the curtains, you can see the outlines of tree branches on a summer day. nothing more than vague outlines. i''ve always been fascinated by what lay behind that curtain; it''s a whole world that i''ll never get to see, probably a scene lost forever. it was the most mysterious thing in the universe, and i would always try to imagine what that summer day looked like behind those curtains. this is kind of what this photograph is like for me. i want to see what''s behind those hills, what the sides of this scene is like, the things you can''t see that are just outside of the frame. it''s fascinating.', '2012-07-07 01:51:08.000000', NULL, 0),
